input.command:
cd /tmp/explore/transport && cat > p22.py <<'EOF'
import sys,time; sys.path.insert(0,'/tmp/explore/transport')
from tlslib import *
full = hdr(an=1)+question('example.net',1)+rr('example.net',1,1,300,bytes([1,2,3,4]))
try:
    out,err,rc,box = runtls(['example.net','-n','https://localhost/dns-query','-H','--colour=never'], doh_handler(lambda r,i: full), 443, timeout=25)
    print("=== -H DoH against real TLS server on 443 ===")
    for k,b in box: print("  %s %r"%(k,b))
    print("  RC=%r OUT=%r ERR=%r"%(rc,out,err))
except Exception as e:
    print("ERR binding:",e)
EOF
PORT_BASE=6300 python3 p22.py 2>&1
